405	// strictCircuitObject decodes one committed circuit record's own member map,
406	// demanding a JSON object with exactly the known top-level fields once. It
407	// scans only the record's own level: the envelope scanner already attributes a
408	// duplicated top-level key to this record, and nested values such as the
409	// constraint definition own their (more precise) strict decoders.
410	func strictCircuitObject(raw []byte, what string) (map[string]json.RawMessage, error) {
411		trimmed := bytes.TrimSpace(raw)
412		if len(trimmed) == 0 || trimmed[0] != '{' {
413			return nil, corruptf("%s must be a JSON object", what)
414		}
415		dec := json.NewDecoder(bytes.NewReader(trimmed))
416		dec.UseNumber()
417		open, err := dec.Token()
418		if err != nil || open != json.Delim('{') {
419			return nil, corruptf("%s must be a JSON object", what)
420		}
421		allowed := make(map[string]bool, len(persistCircuitFields))
422		for _, f := range persistCircuitFields {
423			allowed[f] = true
424		}
425		members := make(map[string]json.RawMessage)
426		for dec.More() {
427			keyTok, err := dec.Token()
428			if err != nil {
429				return nil, corruptf("%s is not valid JSON: %v", what, err)
430			}
431			key, ok := keyTok.(string)
432			if !ok {
433				return nil, corruptf("%s is not valid JSON", what)
434			}
435			if !allowed[key] {
436				return nil, corruptf("%s has unknown field %q", what, key)
437			}
438			if _, repeated := members[key]; repeated {
439				return nil, corruptf("%s contains duplicate field %q", what, key)
440			}
441			var value json.RawMessage
442			if err := dec.Decode(&value); err != nil {
443				return nil, corruptf("%s is not valid JSON: %v", what, err)
444			}
445			members[key] = value
446		}
447		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
448			return nil, corruptf("%s is not valid JSON", what)
449		}
450		if _, err := dec.Token(); err != io.EOF {
451			return nil, corruptf("%s is not valid JSON: trailing data after the object", what)
452		}
453		return members, nil
454	}
