683	func sortEnvelope(env *envelope) {
684		sort.Slice(env.Circuits, func(i, j int) bool {
685			if env.Circuits[i].Name != env.Circuits[j].Name {
686				return env.Circuits[i].Name < env.Circuits[j].Name
687			}
688			return env.Circuits[i].Version < env.Circuits[j].Version
689		})
690		sort.Slice(env.Setups, func(i, j int) bool {
691			if env.Setups[i].Name != env.Setups[j].Name {
692				return env.Setups[i].Name < env.Setups[j].Name
693			}
694			return env.Setups[i].Version < env.Setups[j].Version
695		})
696		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
697		sort.Slice(env.Artifacts, func(i, j int) bool {
698			if env.Artifacts[i].Name != env.Artifacts[j].Name {
699				return env.Artifacts[i].Name < env.Artifacts[j].Name
700			}
701			return env.Artifacts[i].Version < env.Artifacts[j].Version
702		})
703	}
704	
705	// validateEnvelope re-checks every invariant on load so a tampered or
706	// hand-edited file cannot bypass the domain rules.
707	func validateEnvelope(env envelope) error {
708		seenCircuit := make(map[[2]string]bool)
709		circuitOK := make(map[[2]string]bool)
710		for i, c := range env.Circuits {
711			key := [2]string{c.Name, itoa(c.Version)}
712			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
713				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
714			}
715			if c.Version <= 0 {
716				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
717			}
718			if seenCircuit[key] {
719				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
720			}
721			seenCircuit[key] = true
722			if c.Constraints <= 0 {
723				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
724			}
725			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
726				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
727			}
728			if c.Definition != nil {
729				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
730					return err
731				}
732			}
733			circuitOK[key] = true
734		}
735		seenSetup := make(map[[2]string]bool)
736		for i, p := range env.Setups {
737			key := [2]string{p.Name, itoa(p.Version)}
738			if !circuitOK[key] {
739				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
740			}
741			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
742			if c == nil || !c.Frozen {
743				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
744			}
745			if seenSetup[key] {
746				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
747			}
748			seenSetup[key] = true
749		}
750		seenJob := make(map[string]bool)
751		for i, j := range env.Jobs {
752			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
753				return fmt.Errorf("job #%d has an empty or blank id", i+1)
754			}
755			if seenJob[j.ID] {
756				return fmt.Errorf("job %q appears more than once", j.ID)
757			}
758			seenJob[j.ID] = true
759			if j.Kind != "prove" {
760				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
761			}
762			if j.Attempt <= 0 {
763				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
764			}
765			key := [2]string{j.Circuit, itoa(j.Version)}
766			if !circuitOK[key] {
767				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
768			}
769			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
770			if c == nil || !c.Frozen {
771				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
772			}
773			if !seenSetup[key] {
774				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
775			}
776			// A recorded compiled-artifact binding must still resolve against the
777			// pinned version's artifact; a dangling or mismatched binding makes
778			// the file unreadable rather than silently dropping the binding.
779			if j.CompiledHash != "" {
780				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
781				if artifact == nil {
782					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
783				}
784				if artifact.Hash != j.CompiledHash {
785					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
786						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
787				}
788			}
789		}
790		seenArtifact := make(map[[2]string]bool)
791		for i, a := range env.Artifacts {
792			key := [2]string{a.Name, itoa(a.Version)}
793			if !circuitOK[key] {
794				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
795			}
796			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
797			if c == nil || !c.Frozen {
798				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
799			}
800			if seenArtifact[key] {
801				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
802			}
803			seenArtifact[key] = true
804			if c.Definition == nil {
805				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
806			}
807			if a.Constraints != c.Constraints {
808				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
809					a.Name, a.Version, a.Constraints, c.Constraints)
810			}
811			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
812			if err != nil {
813				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
814			}
815			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
816				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
817			}
818			wantHash := artifactHash(a.Name, a.Version, def)
819			if a.Hash != wantHash {
820				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
821					a.Name, a.Version, a.Hash, wantHash)
822			}
823		}
824		return nil
825	}
826	
827	// validatePersistDefinition re-validates a stored definition against its
828	// version's declared counts: prime modulus, in-range wires and an exact
829	// constraint count match.
830	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
831		parsed, err := definitionFromPersist(*def, public, private)
832		if err != nil {
833			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
834		}
835		if !parsed.compatibleWith(constraints, public, private) {
836			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
837		}
838		return nil
839	}
840	
841	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
842		for i := range cs {
843			if cs[i].Name == name && cs[i].Version == version {
844				return &cs[i]
845			}
846		}
847		return nil
848	}
849	
850	func itoa(v int) string { return fmt.Sprintf("%d", v) }
851

