259					t.Fatalf("counts-only record (%s definition) refused: %v", mode, err)
260				}
261				if _, err := s2.GetDefinition("bare", 1); !errors.Is(err, ErrDefinitionMissing) {
262					t.Fatalf("want ErrDefinitionMissing, got %v", err)
