39			{"modulus negative", `{"modulus":"-7","constraints":[]}`},
40			{"modulus one", `{"modulus":"1","constraints":[]}`},
41			{"modulus too large", `{"modulus":"2147483648","constraints":[]}`},
42			{"modulus composite", `{"modulus":"9","constraints":[]}`},
43			{"modulus even", `{"modulus":"4","constraints":[]}`},
44			{"constraints not array", `{"modulus":"7","constraints":{}}`},
45			{"constraints null", `{"modulus":"7","constraints":null}`},
46			{"count mismatch", `{"modulus":"7","constraints":[]}`},
47			{"constraint not object", `{"modulus":"7","constraints":[1]}`},
48			{"unknown constraint field", `{"modulus":"7","constraints":[{"a":[],"b":[],"c":[],"z":1}]}`},
49			{"missing side a", `{"modulus":"7","constraints":[{"b":[],"c":[]}]}`},
50			{"side null", `{"modulus":"7","constraints":[{"a":null,"b":[],"c":[]}]}`},
