71		for _, tc := range cases {
72			t.Run(tc.name, func(t *testing.T) {
73				if _, err := parseDefinitionJSON([]byte(tc.doc), pub, priv, count); err == nil {
74					t.Fatalf("expected rejection for %s", tc.name)
75				} else if !errors.Is(err, ErrInvalidArgument) {
76					t.Fatalf("want ErrInvalidArgument for %s, got %v", tc.name, err)
