82	func TestParseDefinitionAcceptsCanonicalShapes(t *testing.T) {
83		// Empty side arrays mean zero; wire 0 is always available; duplicate
84		// wires merge; zero terms are dropped.
85		doc := `{"modulus":"7","constraints":[
86			{"a":[],"b":[{"wire":0,"coeff":"1"}],"c":[]},
87			{"a":[{"wire":2,"coeff":"8"},{"wire":2,"coeff":"-1"},{"wire":1,"coeff":"0"}],"b":[],"c":[{"wire":2,"coeff":"0"}]}]}`
88		d, err := parseDefinitionJSON([]byte(doc), 1, 1, 2)
89		if err != nil {
90			t.Fatal(err)
91		}
92		if d.modulus != 7 || len(d.constraints) != 2 {
93			t.Fatalf("unexpected parse: %+v", d)
94		}
95		// 8 + (-1) = 7 ≡ 0 mod 7, so the merged wire-2 term must have been
96		// dropped; the explicit zero wire-1 term too.
97		if len(d.constraints[1].a) != 0 {
98			t.Fatalf("expected merged-to-zero terms dropped, got %+v", d.constraints[1].a)
99		}
100		if len(d.constraints[1].c) != 0 {
101			t.Fatalf("expected explicit zero term dropped, got %+v", d.constraints[1].c)
102		}
103	}
