105	func TestDeterministicPrimality(t *testing.T) {
106		primes := []int64{2, 3, 5, 7, 11, 13, 2147483647, 2147483629}
107		for _, p := range primes {
108			if !isPrime(p) {
109				t.Errorf("%d is prime but reported composite", p)
110			}
111		}
112		composites := []int64{1, 4, 9, 561, 1105, 25326001, 2147483646}
113		for _, n := range composites {
114			if isPrime(n) {
115				t.Errorf("%d is composite but reported prime", n)
116			}
117		}
118	}
