122	func hashOfDoc(t *testing.T, doc string, name string, version, pub, priv, count int) string {
123		t.Helper()
124		d, err := parseDefinitionJSON([]byte(doc), pub, priv, count)
125		if err != nil {
126			t.Fatalf("parse: %v\n%s", err, doc)
