132		base := `{"modulus":"7","constraints":[
133			{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":2,"coeff":"2"},{"wire":0,"coeff":"0"}],"c":[{"wire":0,"coeff":"3"}]}]}`
