152			// A huge coefficient congruent to the small one mod 7 (1 + 7·10^24).
153			`{"modulus":"7","constraints":[
154				{"a":[{"wire":1,"coeff":"7000000000000000000000001"}],"b":[{"wire":2,"coeff":"2"}],"c":[{"wire":0,"coeff":"3"}]}]}`,
155		}
