446	// Both entry points run the same binding and verdict rules: the same
447	// frozen version, hash and legal inputs yield identical conclusions, and
448	// the same gating errors in the same order.
449	func TestCheckInputEntryPointsEquivalent(t *testing.T) {
450		s := openTestStore(t)
451		seedDraftWithDef(t, s, "c", 1, 1, 1, validDef)
452		s.FreezeCircuit("c", 1)
453		a, _ := s.CompileCircuit("c", 1)
454	
455		docs := map[string]string{
456			"good":       `{"public":["2"],"private":["3"]}`,
457			"negative":   `{"public":["-5"],"private":["-4"]}`,
458			"huge":       `{"public":["7000000000000000000000002"],"private":["3"]}`,
459			"unsatisfy":  `{"public":["2"],"private":["4"]}`,
460			"badwitness": `{"public":["2"]}`,
461		}
462		for name, doc := range docs {
463			t.Run(name, func(t *testing.T) {
464				path := writeTempJSON(t, doc)
465				fileRes, fileErr := s.CheckInputFile("c", 1, a.Hash, path)
466				if name == "badwitness" {
467					if !errors.Is(fileErr, ErrInvalidInput) {
468						t.Fatalf("file entry: want input format error, got %v", fileErr)
469					}
470					// The JSON witness's strict grammar rejects the document
471					// before the shared layout rules run; the in-API witness
472					// instead supplies the arrays directly.
473					if _, err := s.CheckInput("c", 1, a.Hash, Witness{Public: []string{"2", "x"}, Private: []string{"3"}}); !errors.Is(err, ErrInvalidInput) {
474						t.Fatalf("in-API entry: want input format error, got %v", err)
475					}
476					return
477				}
478				if fileErr != nil {
479					t.Fatalf("file entry: %v", fileErr)
480				}
481				w, werr := parseWitness([]byte(doc), 1, 1)
482				if werr != nil {
483					t.Fatal(werr)
484				}
485				directRes, err := s.CheckInput("c", 1, a.Hash, w)
486				if err != nil {
487					t.Fatalf("direct entry: %v", err)
488				}
489				if directRes != fileRes {
490					t.Fatalf("verdicts differ: direct=%+v file=%+v", directRes, fileRes)
491				}
492			})
493		}
494	
495		// Empty/nil slices are accepted for declared-zero groups through the
496		// direct entry; the JSON entry needs explicit arrays.
497		zero := `{"modulus":"7","constraints":[
498			{"a":[{"wire":0,"coeff":"1"}],"b":[{"wire":0,"coeff":"1"}],"c":[{"wire":0,"coeff":"1"}]}]}`
499		if _, err := s.CreateCircuit(Circuit{Name: "z", Version: 1, Constraints: 1, Description: "z"}); err != nil {
500			t.Fatal(err)
501		}
502		if _, err := s.ImportConstraints("z", 1, writeTempJSON(t, zero)); err != nil {
503			t.Fatal(err)
504		}
505		s.FreezeCircuit("z", 1)
506		az, _ := s.CompileCircuit("z", 1)
507		for _, w := range []Witness{
508			{Public: []string{}, Private: []string{}},
509			{Public: nil, Private: nil},
510		} {
511			res, err := s.CheckInput("z", 1, az.Hash, w)
512			if err != nil || !res.Satisfied || res.Hash != az.Hash {
513				t.Fatalf("nil/empty direct witness %+v: %+v %v", w, res, err)
514			}
515		}
516		path := writeTempJSON(t, `{"public":[],"private":[]}`)
517		res, err := s.CheckInputFile("z", 1, az.Hash, path)
518		if err != nil || !res.Satisfied {
519			t.Fatalf("explicit empty JSON arrays: %+v %v", res, err)
520		}
521		for _, doc := range []string{`{"private":[]}`, `{"public":[]}`, `{"public":null,"private":[]}`} {
522			if _, err := s.CheckInputFile("z", 1, az.Hash, writeTempJSON(t, doc)); !errors.Is(err, ErrInvalidInput) {
523				t.Fatalf("JSON doc %q must stay an input format error, got %v", doc, err)
524			}
525		}
526	}
